describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 5000 = 500, fixed 200 → total 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // Same as sum: 10% of 5000 = 500, fixed 200 → 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts in sum mode → 120% of subtotal
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(60), new PercentageDiscountPolicy(60)],
        "sum",
      );
      // 60% of 1000 = 600, twice = 1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining 9000
      // Second: 10% of 9000 = 900
      // Total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const fixed500ThenPercent10 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // Fixed 500 from 5000 → remaining 4500, then 10% of 4500 = 450 → total 950
      expect(fixed500ThenPercent10.computeDiscountCents(5000)).toBe(950);

      const percent10ThenFixed500 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 10% of 5000 = 500 → remaining 4500, fixed 500 → total 1000
      expect(percent10ThenFixed500.computeDiscountCents(5000)).toBe(1000);
    });

    it("stops compounding once remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      // Fixed 1000 caps to 800 → remaining 0, second fixed → 0
      expect(composite.computeDiscountCents(800)).toBe(800);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

