describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 500, 1)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([line("a", 100, 1)], 2000)).toBe(799);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([line("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([line("a", 100, 1)], 6000)).toBe(0);
    });

    it("charges when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([line("a", 100, 1)], 4999)).toBe(799);
    });

    it("charges flat fee when no freeOver is set", () => {
      const calc = new FlatShippingCalculator(500);
      expect(
        calc.computeShippingCents([line("a", 100, 1)], 999_999),
      ).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 1.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            1.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([noWeightLine("a", 2)], 5000),
      ).toBe(0);
    });

    it("selects the first bracket that fits the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([line("a", 400, 1)], 5000),
      ).toBe(300);
    });

    it("selects exact boundary of first bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([line("a", 500, 1)], 5000),
      ).toBe(300);
    });

    it("moves to second bracket when weight exceeds first", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([line("a", 501, 1)], 5000),
      ).toBe(600);
    });

    it("uses the last bracket's cost as overflow when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([line("a", 6000, 1)], 5000),
      ).toBe(1200);
    });

    it("uses overflowCostCents when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(
        calc.computeShippingCents([line("a", 6000, 1)], 5000),
      ).toBe(2000);
    });

    it("sums weight across multiple lines and multiple quantities", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300g * 2 + 200g * 3 = 1200g → second bracket (≤2000) = 600
      expect(
        calc.computeShippingCents(
          [line("a", 300, 2), line("b", 200, 3)],
          5000,
        ),
      ).toBe(600);
    });

    it("sorts brackets even if provided out of order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(
        calc.computeShippingCents([line("a", 400, 1)], 5000),
      ).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const mkLine = (id: string, price: number, qty: number): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates each line's unitPriceCents from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500)
        .mockResolvedValueOnce(2500),
    };
    const lines = [mkLine("a", 1000, 2), mkLine("b", 2000, 1)];
    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
    expect(result[1]!.quantity).toBe(1);
  });

  it("does not mutate original lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const original = [mkLine("a", 500, 1)];
    await refreshPrices(original, fetcher);
    expect(original[0]!.product.unitPriceCents).toBe(500);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([mkLine("a", 100, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices([mkLine("a", 100, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("returns empty array for empty input", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(
      refreshPrices([mkLine("a", 100, 1)], fetcher),
    ).rejects.toThrow("service down");
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  unitPriceCents: number,
  overrides?: Partial<Product>,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product line", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding the same product twice", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("a")).toBe(false); // already gone
    });

    it("throws for non-existent product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("missing", 1)).toThrow(
        "Product missing is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);

      // Mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals – pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(2000 + 1500);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(3500);
    });

    it("empty cart yields all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("applies discount policy and clamps to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(300);
      expect(totals.totalCents).toBe(700);
    });

    it("clamps discount that exceeds subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });

    it("computes tax on the discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({ discountPolicy, taxCalculator });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      // Discounted subtotal = 1000 - 200 = 800
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.taxCents).toBe(80);
      expect(totals.totalCents).toBe(800 + 80);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("passes discounted subtotal to shipping calculator", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700, // discounted subtotal
      );
      expect(totals.shippingCents).toBe(500);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(45),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      // discountedSubtotal = 1000 - 100 = 900
      expect(totals.totalCents).toBe(900 + 45 + 799);
    });

    it("uses custom region for tax calculation", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({ taxCalculator, region: "FR" });
      cart.add(product("a", 1000), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for basic checkout", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.product.id).toBe("a");
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("validates inventory and passes for in-stock items", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "discontinued" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(2);
        expect(invErr.message).toBe("discontinued");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(0),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator, region: "US-CA" });
      cart.add(product("a", 10000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(875); // 8.75% of 10000
      expect(result.totals.totalCents).toBe(10000 + 875);
    });

    it("composes discount + async tax + shipping", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(product("a", 5000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=5000, discount=500, discountedSubtotal=4500
      // tax = 10% of 4500 = 450
      // shipping = 799
      expect(result.totals.subtotalCents).toBe(5000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(450);
      expect(result.totals.shippingCents).toBe(799);
      expect(result.totals.totalCents).toBe(4500 + 450 + 799);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service error",
      );
    });

    it("checks inventory for all lines in order", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("combines priceFetcher and inventoryChecker", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ priceFetcher, inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2400); // 1200 * 2
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });
  });
});

