+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(
+        calc.computeShippingCents([noWeightLine("a", 2)], 5000),
+      ).toBe(0);
+    });
+
+    it("selects the first bracket that fits the weight", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(
+        calc.computeShippingCents([line("a", 400, 1)], 5000),
+      ).toBe(300);
+    });
+
+    it("selects exact boundary of first bracket", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(
+        calc.computeShippingCents([line("a", 500, 1)], 5000),
+      ).toBe(300);
+    });
+
+    it("moves to second bracket when weight exceeds first", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(
+        calc.computeShippingCents([line("a", 501, 1)], 5000),
+      ).toBe(600);
+    });
+
+    it("uses the last bracket's cost as overflow when no overflow specified", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(
+        calc.computeShippingCents([line("a", 6000, 1)], 5000),
+      ).toBe(1200);
+    });
+
+    it("uses overflowCostCents when weight exceeds all brackets", () => {
+      const calc = new WeightBasedShippingCalculator(brackets, 2000);
+      expect(
+        calc.computeShippingCents([line("a", 6000, 1)], 5000),
+      ).toBe(2000);
+    });
+
+    it("sums weight across multiple lines and multiple quantities", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 300g * 2 + 200g * 3 = 1200g → second bracket (≤2000) = 600
+      expect(
+        calc.computeShippingCents(
+          [line("a", 300, 2), line("b", 200, 3)],
+          5000,
+        ),
+      ).toBe(600);
+    });
+
+    it("sorts brackets even if provided out of order", () => {
+      const unsorted = [
+        { upToGrams: 5000, costCents: 1200 },
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 2000, costCents: 600 },
+      ];
+      const calc = new WeightBasedShippingCalculator(unsorted);
+      expect(
+        calc.computeShippingCents([line("a", 400, 1)], 5000),
+      ).toBe(300);
+    });
+  });
+});
